  page.capture                           offset=AbsoluteStatic(0x00) size=Fixed(4) align=Aligned(8) repr=MemoryIdentical atomic=NonAtomic
  page.version                           offset=AbsoluteStatic(0x04) size=Fixed(1) align=Aligned(4) repr=MemoryIdentical atomic=AtomicWord
  page.header_type                       offset=AbsoluteStatic(0x05) size=Fixed(1) align=Aligned(1) repr=MemoryIdentical atomic=AtomicWord
  page.granule_position                  offset=AbsoluteStatic(0x06) size=Fixed(8) align=Aligned(2) repr=ValueConverted atomic=NonAtomic
  page.serial                            offset=AbsoluteStatic(0x0E) size=Fixed(4) align=Aligned(2) repr=ValueConverted atomic=NonAtomic
  page.sequence                          offset=AbsoluteStatic(0x12) size=Fixed(4) align=Aligned(2) repr=ValueConverted atomic=NonAtomic
  page.checksum                          offset=AbsoluteStatic(0x16) size=Fixed(4) align=Aligned(2) repr=ValueConverted atomic=NonAtomic
  page.segment_count                     offset=AbsoluteStatic(0x1A) size=Fixed(1) align=Aligned(2) repr=MemoryIdentical atomic=AtomicWord
  page.lacing                            offset=AbsoluteStatic(0x1B) size=Bounded(0, 255) align=Aligned(1) repr=MemoryIdentical atomic=AtomicWord mutate=Shifting
  page.body                              offset=Dynamic size=Unbounded align=Unaligned repr=MemoryIdentical atomic=AtomicWord mutate=Shifting address=Unstable

